import{_ as t,H as l,o as s,c as r,aO as i,q as p,s as e,a as d,l as o,aU as h}from"./chunks/framework.vjUPZZJn.js";const f=JSON.parse('{"title":"SIGSEGV core 排查：区分真实崩溃与 kill 自杀","description":"","frontmatter":{"date":"2026-09-23T21:10:00.000Z","title":"SIGSEGV core 排查：区分真实崩溃与 kill 自杀","source":[["1-知识/问题记录/bug40611-bus-agent崩溃排查记录"]],"tags":["问题排查","Linux","gdb","信号"],"categories":["问题排查"],"permalink":"/pages/e553e6"},"headers":[],"relativePath":"问题排查/SIGSEGV core 排查：区分真实崩溃与 kill 自杀.md","filePath":"问题排查/SIGSEGV core 排查：区分真实崩溃与 kill 自杀.md","lastUpdated":1790179862000}'),c={name:"问题排查/SIGSEGV core 排查：区分真实崩溃与 kill 自杀.md"};function k(g,a,u,E,b,_){const n=l("Mermaid");return s(),r("div",null,[a[2]||(a[2]=i(`<h1 id="sigsegv-core-排查-区分真实崩溃与-kill-自杀" tabindex="-1">SIGSEGV core 排查：区分真实崩溃与 kill 自杀 <a class="header-anchor" href="#sigsegv-core-排查-区分真实崩溃与-kill-自杀" aria-label="Permalink to &quot;SIGSEGV core 排查：区分真实崩溃与 kill 自杀&quot;">​</a></h1> <p>多线程服务留下一个 SIGSEGV core，gdb 打开后崩溃线程停在 <code>pthread_cond_wait</code> 或其他等待函数里——这种栈通常不是真实的访存错误现场。本文介绍一套判别方法：先用 gdb 的 <code>$_siginfo</code> 判断信号来源，再决定是否信任崩溃线程的栈，最后给出定位调用方与还原触发场景的步骤。方法适用于任何 Linux 多线程程序的 core 分析。</p> <h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2> <p>一台 ARM64 设备上的多线程服务（约 80 个线程）死亡并留下 core。gdb 打开后，崩溃线程是主线程，栈顶停在自己栈对象的条件变量等待里：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#0  __pthread_cond_wait_common</span></span>
<span class="line"><span>#1  std::condition_variable::wait</span></span>
<span class="line"><span>#2  NodeBase::Join (this=...) at node_base.hpp:259</span></span>
<span class="line"><span>#3  main</span></span>
<span class="line"><span>Program terminated with signal SIGSEGV</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="为什么这个栈可疑" tabindex="-1">为什么这个栈可疑 <a class="header-anchor" href="#为什么这个栈可疑" aria-label="Permalink to &quot;为什么这个栈可疑&quot;">​</a></h2> <p>等待中的线程，其栈帧和等待所用的 mutex、条件变量在等待期间始终有效且被映射，在等待点本身产生访存错误的可能性极低。遇到这种 core，应先怀疑信号是被送进来的，而不是这个位置的访存错误——直接顺着 bt 去查 <code>NodeBase::Join</code> 的代码会被带偏。</p> <h2 id="第一步-用-siginfo-判断信号来源" tabindex="-1">第一步：用 $_siginfo 判断信号来源 <a class="header-anchor" href="#第一步-用-siginfo-判断信号来源" aria-label="Permalink to &quot;第一步：用 $_siginfo 判断信号来源&quot;">​</a></h2> <div class="language-gdb vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">gdb</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) p $_siginfo</span></span>
<span class="line"><span>{si_signo = 11, si_errno = 0, si_code = 0,</span></span>
<span class="line"><span> _kill = {si_pid = 1161, si_uid = 0}, _sigfault = {si_addr = 0x489}, ...}</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>si_code 是判别依据，取值与含义如下（数值来自 Linux 内核头文件 <a href="https://github.com/torvalds/linux/blob/master/include/uapi/asm-generic/siginfo.h" target="_blank" rel="noreferrer">asm-generic/siginfo.h</a>，语义见 <a href="https://man7.org/linux/man-pages/man2/sigaction.2.html" target="_blank" rel="noreferrer">sigaction(2)</a>）：</p> <table tabindex="0"><thead><tr><th>si_code</th> <th>值</th> <th>含义</th> <th>关键字段</th></tr></thead> <tbody><tr><td>SI_USER</td> <td>0</td> <td>kill() / raise() 发送</td> <td>si_pid = 发送者 PID</td></tr> <tr><td>SI_TKILL</td> <td>-6</td> <td>tgkill() / pthread_kill() 发送</td> <td>si_pid = 发送者 PID</td></tr> <tr><td>SEGV_MAPERR</td> <td>1</td> <td>访存错误：地址未映射</td> <td>si_addr = 出错地址</td></tr> <tr><td>SEGV_ACCERR</td> <td>2</td> <td>访存错误：权限不符</td> <td>si_addr = 出错地址</td></tr></tbody></table> <p>本例 si_code = 0（SI_USER），si_pid = 1161 恰好等于进程自身 PID（core 文件名里也带着 1161）——即进程内某个线程执行了 <code>kill(getpid(), 11)</code>，把 SIGSEGV 发给了自己的进程。</p> <p>顺带解释 <code>_sigfault.si_addr = 0x489</code>：0x489 正是 1161 的十六进制。siginfo_t 中 <code>_kill</code> 与 <code>_sigfault</code> 是同一块内存按 union 分支读取的别名，这里从 si_addr 读出来的其实是 si_pid 的值。SI_USER 场景下不要把 si_addr 当作出错地址。</p> <h2 id="第二步-理解信号为什么落在等待线程上" tabindex="-1">第二步：理解信号为什么落在等待线程上 <a class="header-anchor" href="#第二步-理解信号为什么落在等待线程上" aria-label="Permalink to &quot;第二步：理解信号为什么落在等待线程上&quot;">​</a></h2> <p><a href="https://man7.org/linux/man-pages/man7/signal.7.html" target="_blank" rel="noreferrer">signal(7)</a> 对进程导向信号的递送规则：信号会递送给任意一个未阻塞该信号的线程；多个线程都未阻塞时，内核任选一个。<code>kill(getpid(), sig)</code> 发出的正是进程导向信号，于是：</p> `,28)),(s(),p(h,null,{default:e(()=>[o(n,{id:"mermaid-114",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E6%9F%90%E7%BA%BF%E7%A8%8B%E8%A7%A6%E5%8F%91%E5%BA%93%E5%86%85%20fatal%22%5D%20--%3E%20B%5B%22%E5%BC%82%E5%B8%B8%E5%A4%84%E7%90%86%E5%99%A8%E6%81%A2%E5%A4%8D%20SIG_DFL%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22kill(getpid()%2C%20SIGSEGV)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E5%86%85%E6%A0%B8%E4%BB%BB%E9%80%89%E4%B8%80%E4%B8%AA%3Cbr%2F%3E%E6%9C%AA%E9%98%BB%E5%A1%9E%E7%BA%BF%E7%A8%8B%E9%80%92%E9%80%81%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E7%9D%A1%E5%9C%A8%20cond_wait%20%E7%9A%84%E4%B8%BB%E7%BA%BF%E7%A8%8B%E6%8E%A5%E8%B5%B0%E4%BF%A1%E5%8F%B7%3Cbr%2F%3E%E6%88%90%E4%B8%BA%20core%20%E9%87%8C%E7%9A%84%E5%B4%A9%E6%BA%83%E7%BA%BF%E7%A8%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(`
          Loading...
        `,-1)])]),_:1})),a[3]||(a[3]=i(`<p>core 里记录的&quot;崩溃线程&quot;与真正肇事的线程没有任何关系，崩在哪个线程是随机的。</p> <h2 id="第三步-全线程-bt-确认没有别的-fault-现场" tabindex="-1">第三步：全线程 bt 确认没有别的 fault 现场 <a class="header-anchor" href="#第三步-全线程-bt-确认没有别的-fault-现场" aria-label="Permalink to &quot;第三步：全线程 bt 确认没有别的 fault 现场&quot;">​</a></h2> <p>用 <code>thread apply all bt</code> 导出所有线程栈，按&quot;0 号帧是阻塞等待&quot;过滤，看是否还有线程停在可疑 PC 上：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/^Thread [0-9]+/{t=$0} /#0/{if ($0 !~ /futex|epoll|poll|read|write|nanosleep|clock_nanosleep|accept|msgrcv|recv|__select/) print t}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bt.txt</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>本例 82 个线程过滤后只剩两个：一个在消息循环的时钟调用里，一个在消息反序列化的内存分配里，都是正常业务。没有任何线程停在错误地址或信号返回帧上——发送 kill 的线程送完信号已经回到等待。这一步把&quot;另有线程踩了坏地址&quot;的可能性排除掉，结论收敛到 kill 自杀。</p> <h2 id="第四步-反汇编找-kill-的调用方" tabindex="-1">第四步：反汇编找 kill 的调用方 <a class="header-anchor" href="#第四步-反汇编找-kill-的调用方" aria-label="Permalink to &quot;第四步：反汇编找 kill 的调用方&quot;">​</a></h2> <p>剩下的问题是&quot;谁调用了 kill&quot;。在本例的进程中，只有一个模块导入了 kill 符号：一个商用闭源实时协议栈库。反汇编定位到它注册的异常处理器，逻辑如下（示意）：</p> <div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">exception_handler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> sig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    dump_internal_trace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 栈内跟踪转储 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    set_fatal_flag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         /* 置全局 fatal 标志 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sig, SIG_DFL);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     /* 恢复信号默认处置 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    kill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getpid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), sig);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 重发信号，按默认动作终止并生成 core */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这是嵌入式实时栈里常见的一种错误处理模式：库内部 fatal 后通过重发信号自杀，让进程按信号默认动作终止并留下 core。副作用是 core 的表面现象（崩溃线程、崩溃位置）与真实原因完全脱节。</p> <p>库的全局状态对象可以作为佐证：core 里该对象的 fatal 标志已置位、运行状态为正常运行态，说明异常处理器确实执行过，且死亡不发生在初始化或关闭流程中。</p> <h2 id="触发场景还原" tabindex="-1">触发场景还原 <a class="header-anchor" href="#触发场景还原" aria-label="Permalink to &quot;触发场景还原&quot;">​</a></h2> <p>日志时间线还原出根因：上位界面的一次操作让协议栈在 231ms 内被连续 start 两次，中间没有 stop，启动入口也没有防重入保护；协议栈二次初始化后在运行态出 fatal，走到上面那条自杀路径。这类&quot;无防重入保护的重复初始化&quot;是此类崩溃的常见根因，修复方向是给初始化入口加状态防重入（启动中或已启动时对后续请求去重，或保证完整的 stop→start 序列），同时排查触发事件为何被重复投递。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>core 崩在等待函数（futex / cond_wait / poll / read 等）时，先 <code>p $_siginfo</code> 再看 bt。</li> <li>si_code = SI_USER 且 si_pid = 自身 PID，说明是进程内 kill 自杀；此时崩溃线程的栈没有参考价值。si_code = SEGV_MAPERR / SEGV_ACCERR 才是真实访存错误，崩溃线程的栈这时才值得细看。</li> <li>SI_USER 场景下 si_addr 是 si_pid 的 union 别名，不要当作出错地址。</li> <li>自杀信号是进程导向的，任意未阻塞线程都可能接走，崩在哪个线程是随机的。</li> <li>定位调用方：全线程 bt 过滤等待帧排除其他 fault 现场，再从导入符号表找 kill 的引用并反汇编。</li> <li>闭源实时库常采用&quot;恢复默认处置后重发信号&quot;的自杀模式，core 现场与根因脱节是这个模式的特征。</li></ul> <p>参考：<a href="https://man7.org/linux/man-pages/man7/signal.7.html" target="_blank" rel="noreferrer">signal(7)</a> · <a href="https://man7.org/linux/man-pages/man2/sigaction.2.html" target="_blank" rel="noreferrer">sigaction(2)</a> · <a href="https://github.com/torvalds/linux/blob/master/include/uapi/asm-generic/siginfo.h" target="_blank" rel="noreferrer">asm-generic/siginfo.h</a></p>`,27))])}const B=t(c,[["render",k]]);export{f as __pageData,B as default};
